trial_validation_and_neutral_guard:
let mut trial = JLayout::from_snapshot(&sep.layout.save());
for &key in &changed_keys {
    trial.remove_item(key);
}
for (snapshot, start) in
    [(receiver_snapshot, offset), (source_snapshot, last_offset)]
{
    for p in JLayout::from_snapshot(&snapshot).placed_items().values() {
        trial.place_item(p.item(), shift(p.d_transf(), start));
    }
}
self.clock.charge(
    Work::RegisteredItem,
    (sep.layout.placed_items().len() + changed_keys.len()) as f64,
);
let report = self.exchange_report(strip, frozen, &trial, shape)?;
if !report.valid {
    self.stats.rejected_layouts += 1;
    continue;
}
let after = report.metrics.as_ref().expect("valid exchange");
if exchange_increases_material(before, after)
    || self.clock.now() >= exchange_until
{
    continue;
}
// Same inventory can still improve the geometry, but a
// flat material result must not consume the sole exchange.
if same_original_inventory(&members, &victims)
    && after.material_area >= before.material_area
{
    self.stats.neutral_exchange_rejections += 1;
    continue;
}
